using System.ComponentModel;
using System.Net.Http.Headers;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var notebook = new Notebook();
using var httpClient = new HttpClient();
httpClient.DefaultRequestHeaders.UserAgent.Add(new ProductInfoHeaderValue("ResearchAgent", "1.0"));

var tools = new AITool[]
{
    AIFunctionFactory.Create(SearchWeb, "search_web",
        "Search the web for a query and return a list of result snippets with URLs."),
    AIFunctionFactory.Create(FetchPage, "fetch_page",
        "Fetch and extract the text content of a web page given its URL."),
    AIFunctionFactory.Create(notebook.TakeNote, "take_note",
        "Save a research note. Use this to record key findings as you research."),
    AIFunctionFactory.Create(notebook.GetNotes, "get_notes",
        "Retrieve all research notes taken so far."),
};

// --- Agent -------------------------------------------------------------------

IChatClient client = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = client.AsAIAgent(
    instructions: """
        You are a research agent. When given a topic:
        1. Search the web for relevant information using the search_web tool.
        2. Fetch promising pages with fetch_page to get detailed content.
        3. Use take_note to record important findings as you go.
        4. After gathering enough information (at least 3-5 sources), retrieve
           your notes with get_notes and produce a well-structured summary with
           source citations.
        Be thorough but concise. Always cite your sources.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Main loop ---------------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (type 'quit')       ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic: ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    notebook.Clear();

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching… (this may take a moment)\n");
    Console.ResetColor();

    try
    {
        var runOptions = new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 4096,
            },
        };

        await foreach (var update in agent.RunStreamingAsync(
            topic, session: null, options: runOptions))
        {
            if (update.Text is { } text)
            {
                Console.Write(text);
            }
        }

        Console.WriteLine("\n");
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.Error.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
        Console.WriteLine();
    }
}

Console.WriteLine("Goodbye!");
return;

// --- Tool implementations ----------------------------------------------------

[Description("Search the web for a query and return result snippets with URLs.")]
async Task<string> SearchWeb(
    [Description("The search query")] string query,
    CancellationToken cancellationToken = default)
{
    try
    {
        // Use DuckDuckGo HTML search (no API key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";
        var html = await httpClient.GetStringAsync(url, cancellationToken);

        // Extract result titles, snippets, and URLs from the HTML
        var results = Regex.Matches(html,
            @"<a[^>]+class=""result__a""[^>]+href=""([^""]+)""[^>]*>(.*?)</a>.*?<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);

        if (results.Count == 0)
        {
            return "No search results found.";
        }

        var output = new List<string>();
        foreach (Match match in results.Take(5))
        {
            var resultUrl = ExtractUrl(match.Groups[1].Value);
            var title = StripHtml(match.Groups[2].Value);
            var snippet = StripHtml(match.Groups[3].Value);
            output.Add($"- [{title}]({resultUrl})\n  {snippet}");
        }

        return string.Join("\n\n", output);
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

[Description("Fetch the text content of a web page.")]
async Task<string> FetchPage(
    [Description("The URL of the page to fetch")] string url,
    CancellationToken cancellationToken = default)
{
    try
    {
        var html = await httpClient.GetStringAsync(url, cancellationToken);

        // Strip scripts, styles, and tags to get readable text
        var text = Regex.Replace(html, @"<script[^>]*>[\s\S]*?</script>", " ", RegexOptions.IgnoreCase);
        text = Regex.Replace(text, @"<style[^>]*>[\s\S]*?</style>", " ", RegexOptions.IgnoreCase);
        text = Regex.Replace(text, @"<[^>]+>", " ");
        text = System.Net.WebUtility.HtmlDecode(text);
        text = Regex.Replace(text, @"\s+", " ").Trim();

        const int maxLength = 4000;
        if (text.Length > maxLength)
        {
            text = text[..maxLength] + "… [truncated]";
        }

        return string.IsNullOrWhiteSpace(text) ? "Page contained no readable text." : text;
    }
    catch (Exception ex)
    {
        return $"Failed to fetch page: {ex.Message}";
    }
}

static string StripHtml(string html) =>
    System.Net.WebUtility.HtmlDecode(Regex.Replace(html, @"<[^>]+>", "")).Trim();

static string ExtractUrl(string duckDuckGoRedirect)
{
    // DDG wraps URLs in a redirect; extract the actual URL
    var match = Regex.Match(duckDuckGoRedirect, @"uddg=([^&]+)");
    return match.Success ? Uri.UnescapeDataString(match.Groups[1].Value) : duckDuckGoRedirect;
}

// --- Notebook ----------------------------------------------------------------

using Microsoft.Agents.AI;

sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note with a key finding.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all research notes taken so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes taken yet.";
        }

        return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    public void Clear() => _notes.Clear();
}

