+httpClient.DefaultRequestHeaders.UserAgent.Add(new ProductInfoHeaderValue("ResearchAgent", "1.0"));
+
+var tools = new AITool[]
+{
+    AIFunctionFactory.Create(SearchWeb, "search_web",
+        "Search the web for a query and return a list of result snippets with URLs."),
+    AIFunctionFactory.Create(FetchPage, "fetch_page",
+        "Fetch and extract the text content of a web page given its URL."),
+    AIFunctionFactory.Create(notebook.TakeNote, "take_note",
+        "Save a research note. Use this to record key findings as you research."),
+    AIFunctionFactory.Create(notebook.GetNotes, "get_notes",
+        "Retrieve all research notes taken so far."),
+};
+
+// --- Agent -------------------------------------------------------------------
+
+IChatClient client = new OpenAI.OpenAIClient(apiKey)
+    .GetChatClient(modelId)
+    .AsIChatClient();
+
+var agent = client.AsAIAgent(
+    instructions: """
+        You are a research agent. When given a topic:
+        1. Search the web for relevant information using the search_web tool.
+        2. Fetch promising pages with fetch_page to get detailed content.
+        3. Use take_note to record important findings as you go.
+        4. After gathering enough information (at least 3-5 sources), retrieve
+           your notes with get_notes and produce a well-structured summary with
+           source citations.
+        Be thorough but concise. Always cite your sources.
+        """,
+    name: "ResearchAgent",
+    description: "An agent that researches topics by searching the web and summarizing findings.",
+    tools: tools);
+
+// --- Main loop ---------------------------------------------------------------
+
+Console.WriteLine("╔══════════════════════════════════════════╗");
+Console.WriteLine("║       Research Agent (type 'quit')       ║");
+Console.WriteLine("╚══════════════════════════════════════════╝");
+Console.WriteLine();
+
+while (true)
+{
+    Console.ForegroundColor = ConsoleColor.Cyan;
+    Console.Write("Research topic: ");
+    Console.ResetColor();
+
+    var topic = Console.ReadLine()?.Trim();
+    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
+    {
+        break;
+    }
+
+    notebook.Clear();
+
+    Console.ForegroundColor = ConsoleColor.DarkGray;
+    Console.WriteLine("Researching… (this may take a moment)\n");
+    Console.ResetColor();
+
+    try
+    {
+        var runOptions = new ChatClientAgentRunOptions
+        {
+            ChatOptions = new ChatOptions
+            {
+                Temperature = 0f,
+                MaxOutputTokens = 4096,
+            },
+        };
+
+        await foreach (var update in agent.RunStreamingAsync(
+            topic, session: null, options: runOptions))
+        {
+            if (update.Text is { } text)
+            {
+                Console.Write(text);
+            }
+        }
+
