+
+[Description("Search the web for a query and return result snippets with URLs.")]
+async Task<string> SearchWeb(
+    [Description("The search query")] string query,
+    CancellationToken cancellationToken = default)
+{
+    try
+    {
+        // Use DuckDuckGo HTML search (no API key required)
+        var encoded = Uri.EscapeDataString(query);
+        var url = $"https://html.duckduckgo.com/html/?q={encoded}";
+        var html = await httpClient.GetStringAsync(url, cancellationToken);
+
+        // Extract result titles, snippets, and URLs from the HTML
+        var results = Regex.Matches(html,
+            @"<a[^>]+class=""result__a""[^>]+href=""([^""]+)""[^>]*>(.*?)</a>.*?<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
+            RegexOptions.Singleline);
+
+        if (results.Count == 0)
+        {
+            return "No search results found.";
+        }
+
+        var output = new List<string>();
+        foreach (Match match in results.Take(5))
+        {
+            var resultUrl = ExtractUrl(match.Groups[1].Value);
+            var title = StripHtml(match.Groups[2].Value);
+            var snippet = StripHtml(match.Groups[3].Value);
+            output.Add($"- [{title}]({resultUrl})\n  {snippet}");
+        }
+
+        return string.Join("\n\n", output);
+    }
+    catch (Exception ex)
+    {
+        return $"Search failed: {ex.Message}";
+    }
+}
+
+[Description("Fetch the text content of a web page.")]
+async Task<string> FetchPage(
+    [Description("The URL of the page to fetch")] string url,
+    CancellationToken cancellationToken = default)
+{
+    try
+    {
+        var html = await httpClient.GetStringAsync(url, cancellationToken);
+
+        // Strip scripts, styles, and tags to get readable text
+        var text = Regex.Replace(html, @"<script[^>]*>[\s\S]*?</script>", " ", RegexOptions.IgnoreCase);
+        text = Regex.Replace(text, @"<style[^>]*>[\s\S]*?</style>", " ", RegexOptions.IgnoreCase);
+        text = Regex.Replace(text, @"<[^>]+>", " ");
+        text = System.Net.WebUtility.HtmlDecode(text);
+        text = Regex.Replace(text, @"\s+", " ").Trim();
+
+        const int maxLength = 4000;
+        if (text.Length > maxLength)
+        {
+            text = text[..maxLength] + "… [truncated]";
+        }
+
+        return string.IsNullOrWhiteSpace(text) ? "Page contained no readable text." : text;
+    }
+    catch (Exception ex)
+    {
+        return $"Failed to fetch page: {ex.Message}";
+    }
+}
+
+static string StripHtml(string html) =>
+    System.Net.WebUtility.HtmlDecode(Regex.Replace(html, @"<[^>]+>", "")).Trim();
+
+static string ExtractUrl(string duckDuckGoRedirect)
+{
+    // DDG wraps URLs in a redirect; extract the actual URL
+    var match = Regex.Match(duckDuckGoRedirect, @"uddg=([^&]+)");
+    return match.Success ? Uri.UnescapeDataString(match.Groups[1].Value) : duckDuckGoRedirect;
+}
+
